import{_ as s,o as e,c as n,a0 as t}from"./chunks/framework.CShDTZbC.js";const m=JSON.parse('{"title":"Import","description":"","frontmatter":{},"headers":[],"relativePath":"syntax/import.md","filePath":"syntax/import.md"}'),p={name:"syntax/import.md"};function i(d,a,l,o,r,c){return e(),n("div",null,[...a[0]||(a[0]=[t(`<h1 id="import" tabindex="-1">Import <a class="header-anchor" href="#import" aria-label="Permalink to &quot;Import&quot;">​</a></h1><p>Import kode dari file lain ke dalam scope saat ini. Import statements harus berada di bagian atas file.</p><h2 id="_1-specific-functions" tabindex="-1">1. Specific functions <a class="header-anchor" href="#_1-specific-functions" aria-label="Permalink to &quot;1. Specific functions&quot;">​</a></h2><p>Import fungsi tertentu dari module. Fungsi langsung tersedia di top-level.</p><div class="language-rupa vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">rupa</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>import create, update from ./modules.a</span></span>
<span class="line"><span></span></span>
<span class="line"><span>create()</span></span>
<span class="line"><span>update()</span></span></code></pre></div><h2 id="_2-wildcard-dengan-namespace" tabindex="-1">2. Wildcard dengan namespace <a class="header-anchor" href="#_2-wildcard-dengan-namespace" aria-label="Permalink to &quot;2. Wildcard dengan namespace&quot;">​</a></h2><p>Import semua fungsi dari beberapa module ke dalam namespace.</p><div class="language-rupa vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">rupa</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>import b.*, c.*, d.* from ./modules as m</span></span>
<span class="line"><span></span></span>
<span class="line"><span>m.login()</span></span>
<span class="line"><span>m.services()</span></span>
<span class="line"><span>m.auth()</span></span></code></pre></div><p>Wildcard flatten semua fungsi ke dalam namespace — <code>b.login</code> menjadi <code>m.login</code>.</p><h2 id="_3-wildcard-dengan-alias" tabindex="-1">3. Wildcard dengan alias <a class="header-anchor" href="#_3-wildcard-dengan-alias" aria-label="Permalink to &quot;3. Wildcard dengan alias&quot;">​</a></h2><p>Import semua fungsi dari module, bind sebagai object dengan nama alias.</p><div class="language-rupa vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">rupa</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>import a.* as form from ./modules</span></span>
<span class="line"><span></span></span>
<span class="line"><span>form.create()</span></span>
<span class="line"><span>form.update()</span></span></code></pre></div><h2 id="_4-mixed-import" tabindex="-1">4. Mixed import <a class="header-anchor" href="#_4-mixed-import" aria-label="Permalink to &quot;4. Mixed import&quot;">​</a></h2><p>Wildcard dan specific function dalam satu statement.</p><div class="language-rupa vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">rupa</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>import a.* as form, b.login, b.register from ./modules</span></span>
<span class="line"><span></span></span>
<span class="line"><span>form.create()   // alias object</span></span>
<span class="line"><span>login()         // top-level</span></span>
<span class="line"><span>register()      // top-level</span></span></code></pre></div><h2 id="_5-full-module-import" tabindex="-1">5. Full module import <a class="header-anchor" href="#_5-full-module-import" aria-label="Permalink to &quot;5. Full module import&quot;">​</a></h2><p>Import seluruh module sebagai nama. Parser mencoba load file langsung, lalu fallback ke sub-module.</p><div class="language-rupa vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">rupa</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>import d from ./modules</span></span>
<span class="line"><span></span></span>
<span class="line"><span>d.auth()</span></span>
<span class="line"><span>d.users()</span></span></code></pre></div><h2 id="_6-stdlib-import" tabindex="-1">6. Stdlib import <a class="header-anchor" href="#_6-stdlib-import" aria-label="Permalink to &quot;6. Stdlib import&quot;">​</a></h2><p>Import dari standard library <code>rupa</code>.</p><div class="language-rupa vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">rupa</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>import os from rupa</span></span>
<span class="line"><span>print(os.info().user)</span></span></code></pre></div><h2 id="_7-stdlib-specific-function" tabindex="-1">7. Stdlib specific function <a class="header-anchor" href="#_7-stdlib-specific-function" aria-label="Permalink to &quot;7. Stdlib specific function&quot;">​</a></h2><p>Import fungsi tertentu dari stdlib module.</p><div class="language-rupa vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">rupa</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>import info from rupa.os</span></span>
<span class="line"><span>print(info())</span></span>
<span class="line"><span></span></span>
<span class="line"><span>import server, stop from rupa.http</span></span>
<span class="line"><span>s = server(8080)</span></span>
<span class="line"><span>stop(s)</span></span></code></pre></div><h2 id="_8-stdlib-wildcard" tabindex="-1">8. Stdlib wildcard <a class="header-anchor" href="#_8-stdlib-wildcard" aria-label="Permalink to &quot;8. Stdlib wildcard&quot;">​</a></h2><p>Import semua fungsi dari stdlib module dengan namespace.</p><div class="language-rupa vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">rupa</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>import http.*, thread.* from rupa as r</span></span>
<span class="line"><span></span></span>
<span class="line"><span>r.http.server(8080)</span></span>
<span class="line"><span>r.thread.sleep(100)</span></span></code></pre></div><h2 id="ringkasan" tabindex="-1">Ringkasan <a class="header-anchor" href="#ringkasan" aria-label="Permalink to &quot;Ringkasan&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Syntax</th><th>Hasil</th></tr></thead><tbody><tr><td><code>import X from ./path.a</code></td><td><code>X()</code> top-level</td></tr><tr><td><code>import X.*, Y.* from ./path as ns</code></td><td><code>ns.func()</code></td></tr><tr><td><code>import X.* as alias from ./path</code></td><td><code>alias.func()</code></td></tr><tr><td><code>import X.a, X.b from ./path</code></td><td><code>a()</code>, <code>b()</code> top-level</td></tr><tr><td><code>import X from ./path</code></td><td><code>X.func()</code></td></tr><tr><td><code>import X from rupa</code></td><td>Seluruh module</td></tr><tr><td><code>import X from rupa.Y</code></td><td>Fungsi dari module</td></tr><tr><td><code>import X, Y from rupa.Y</code></td><td>Beberapa fungsi</td></tr><tr><td><code>import X.*, Y.* from rupa as ns</code></td><td>Wildcard + alias</td></tr></tbody></table>`,29)])])}const h=s(p,[["render",i]]);export{m as __pageData,h as default};
